   302→/// Signed Ethereum transaction.
   303→#[derive(Debug, Clone, Eq, derive_more::AsRef, derive_more::Deref)]
   304→#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
