   307→#[cfg_attr(feature = "serde", serde(rename_all = "camelCase"))]
   308→pub struct TransactionSigned {
   309→    /// Transaction hash
   310→    #[cfg_attr(feature = "serde", serde(skip))]
   311→    hash: OnceLock<TxHash>,
   312→    /// The transaction signature values
   313→    signature: Signature,
   314→    /// Raw transaction info
   315→    #[deref]
   316→    #[as_ref]
   317→    #[cfg_attr(feature = "test-utils", deref_mut)]
   318→    transaction: Transaction,
   319→}
