   334→impl PartialEq for TransactionSigned {
   335→    fn eq(&self, other: &Self) -> bool {
   336→        self.signature == other.signature &&
   337→            self.transaction == other.transaction &&
   338→            self.tx_hash() == other.tx_hash()
   339→    }
   340→}
