   342→impl TransactionSigned {
   343→    /// Creates a new signed transaction from the given transaction, signature and hash.
   344→    pub fn new(transaction: Transaction, signature: Signature, hash: B256) -> Self {
   345→        Self { hash: hash.into(), signature, transaction }
   346→    }
   347→
   348→    /// Returns the transaction hash.
   349→    #[inline]
   350→    pub fn hash(&self) -> &B256 {
   351→        self.hash.get_or_init(|| self.recalculate_hash())
   352→    }
   353→
   354→    /// Splits the transaction into parts.
   355→    pub fn into_parts(self) -> (Transaction, Signature, B256) {
   356→        let hash = *self.hash.get_or_init(|| self.recalculate_hash());
   357→        (self.transaction, self.signature, hash)
   358→    }
   359→}
