   444→impl From<TransactionSigned> for EthereumTxEnvelope<TxEip4844> {
   445→    fn from(value: TransactionSigned) -> Self {
   446→        let (tx, signature, hash) = value.into_parts();
   447→        match tx {
   448→            Transaction::Legacy(tx) => Signed::new_unchecked(tx, signature, hash).into(),
   449→            Transaction::Eip2930(tx) => Signed::new_unchecked(tx, signature, hash).into(),
   450→            Transaction::Eip1559(tx) => Signed::new_unchecked(tx, signature, hash).into(),
   451→            Transaction::Eip4844(tx) => Signed::new_unchecked(tx, signature, hash).into(),
   452→            Transaction::Eip7702(tx) => Signed::new_unchecked(tx, signature, hash).into(),
   453→        }
   454→    }
   455→}
