   459→    fn arbitrary(u: &mut arbitrary::Unstructured<'a>) -> arbitrary::Result<Self> {
   460→        #[expect(unused_mut)]
   461→        let mut transaction = Transaction::arbitrary(u)?;
   462→
   463→        let secp = secp256k1::Secp256k1::new();
   464→        let key_pair = secp256k1::Keypair::new(&secp, &mut rand_08::thread_rng());
   465→        let signature = reth_primitives_traits::crypto::secp256k1::sign_message(
   466→            B256::from_slice(&key_pair.secret_bytes()[..]),
   467→            transaction.signature_hash(),
   468→        )
   469→        .unwrap();
   470→
   471→        Ok(Self { transaction, signature, hash: Default::default() })
   472→    }
   473→}
