   500→impl Decodable2718 for TransactionSigned {
   501→    fn typed_decode(ty: u8, buf: &mut &[u8]) -> Eip2718Result<Self> {
   502→        match ty.try_into().map_err(|_| Eip2718Error::UnexpectedType(ty))? {
   503→            TxType::Legacy => Err(Eip2718Error::UnexpectedType(0)),
   504→            TxType::Eip2930 => {
   505→                let (tx, signature) = TxEip2930::rlp_decode_with_signature(buf)?;
   506→                Ok(Self {
   507→                    transaction: Transaction::Eip2930(tx),
   508→                    signature,
   509→                    hash: Default::default(),
   510→                })
   511→            }
   512→            TxType::Eip1559 => {
   513→                let (tx, signature) = TxEip1559::rlp_decode_with_signature(buf)?;
   514→                Ok(Self {
   515→                    transaction: Transaction::Eip1559(tx),
   516→                    signature,
   517→                    hash: Default::default(),
   518→                })
   519→            }
   520→            TxType::Eip4844 => {
   521→                let (tx, signature) = TxEip4844::rlp_decode_with_signature(buf)?;
   522→                Ok(Self {
   523→                    transaction: Transaction::Eip4844(tx),
   524→                    signature,
   525→                    hash: Default::default(),
   526→                })
   527→            }
   528→            TxType::Eip7702 => {
   529→                let (tx, signature) = TxEip7702::rlp_decode_with_signature(buf)?;
   530→                Ok(Self {
   531→                    transaction: Transaction::Eip7702(tx),
   532→                    signature,
   533→                    hash: Default::default(),
   534→                })
   535→            }
   536→        }
   537→    }
   538→
   539→    fn fallback_decode(buf: &mut &[u8]) -> Eip2718Result<Self> {
   540→        let (tx, signature) = TxLegacy::rlp_decode_with_signature(buf)?;
   541→        Ok(Self { transaction: Transaction::Legacy(tx), signature, hash: Default::default() })
   542→    }
   543→}
