   813→    /// This verifies that the transaction complies with code authorization
   814→    /// restrictions brought by EIP-7702 transaction type:
   815→    /// 1. Any account with a deployed delegation or an in-flight authorization to deploy a
   816→    ///    delegation will only be allowed a certain amount of transaction slots (default 1) instead
   817→    ///    of the standard limit. This is due to the possibility of the account being sweeped by an
   818→    ///    unrelated account.
   819→    /// 2. In case the pool is tracking a pending / queued transaction from a specific account, at
   820→    ///    most one in-flight transaction is allowed; any additional delegated transactions from
   821→    ///    that account will be rejected.
   822→    fn validate_auth(
   823→        &self,
   824→        transaction: &ValidPoolTransaction<T::Transaction>,
   825→        on_chain_nonce: u64,
   826→        on_chain_code_hash: Option<B256>,
   827→    ) -> Result<(), PoolError> {
   828→        // Ensure in-flight limit for delegated accounts or those with a pending authorization.
   829→        self.check_delegation_limit(transaction, on_chain_nonce, on_chain_code_hash)?;
   830→
   831→        if let Some(authority_list) = &transaction.authority_ids {
   832→            for sender_id in authority_list {
   833→                // Ensure authority has at most 1 inflight transaction.
   834→                if self.all_transactions.txs_iter(*sender_id).nth(1).is_some() {
   835→                    return Err(PoolError::new(
   836→                        *transaction.hash(),
   837→                        PoolErrorKind::InvalidTransaction(InvalidPoolTransactionError::Eip7702(
   838→                            Eip7702PoolTransactionError::AuthorityReserved,
   839→                        )),
   840→                    ))
   841→                }
   842→            }
   843→        }
   844→
   845→        Ok(())
   846→    }
