   848→    /// Maintenance task to apply a series of updates.
   849→    ///
   850→    /// This will move/discard the given transaction according to the `PoolUpdate`
   851→    fn process_updates(&mut self, updates: Vec<PoolUpdate>) -> UpdateOutcome<T::Transaction> {
   852→        let mut outcome = UpdateOutcome::default();
   853→        for PoolUpdate { id, current, destination } in updates {
   854→            match destination {
   855→                Destination::Discard => {
   856→                    // remove the transaction from the pool and subpool
   857→                    if let Some(tx) = self.prune_transaction_by_id(&id) {
   858→                        outcome.discarded.push(tx);
   859→                    }
   860→                    self.metrics.removed_transactions.increment(1);
   861→                }
   862→                Destination::Pool(move_to) => {
   863→                    debug_assert_ne!(&move_to, &current, "destination must be different");
   864→                    let moved = self.move_transaction(current, move_to, &id);
